fn is_greater(n: i32, a: &[i32]) -> bool {
    a.iter().all(|&x| n > x)
}

fn main() {
    // Example usage and tests
    assert_eq!(is_greater(5, &[]), true);
    assert_eq!(is_greater(5, &[1, 2, 3, 4]), true);
    assert_eq!(is_greater(5, &[5]), false);
    assert_eq!(is_greater(5, &[2, 7, 1]), false);
    println!("All tests passed.");
}